 $('loading').textContent='As colinas e a floresta estão ganhando forma…';await new Promise(resolve=>requestAnimationFrame(resolve));const grove=makeGrove(THREE,scene);const realm=makeRealm(THREE,scene);const scenery=makeScenery(THREE,scene,grove.padSpots);const farms=makeFarms(THREE,scene);const adventures=makeAdventures(THREE,scene,toast);farms.update(0,0);const atmosphere=makeAtmosphere(THREE,scene);renderer.shadowMap.needsUpdate=true;const reflectionTarget=new THREE.WebGLCubeRenderTarget(256,{generateMipmaps:true,minFilter:THREE.LinearMipmapLinearFilter});const reflectionCamera=new THREE.CubeCamera(.1,2400,reflectionTarget);reflectionCamera.position.set(0,2,0);reflectionCamera.update(renderer,scene);const deer=makeDeer(THREE,scene,grove.trees);grove.occluders.push(...realm.occluders,...scenery.occluders,...farms.occluders,...deer.occluders,...adventures.occluders);
