 function upload(){uniforms.count.value=waves.length;waves.forEach((wave,i)=>{uniforms.sources.value[i].set(wave.x,wave.z,wave.time,wave.amplitude);uniforms.settings.value[i].set(wave.wavelength,wave.persistence);});}
 function render(){bird.setVisible(!journey.active&&document.body.classList.contains('exploring'));fill.position.copy(camera.position);fill.target.position.copy(navigation.controls.target);bird.update(camera,navigation.controls.target,reducedMotion?0:time);uniforms.time.value=time;renderer.render(scene,camera);}
